{"implementation":"def solve(case):
    lengths = case['lengths']
    scores = case['scores']
    budget = case['budget']
    n = len(lengths)
    dp = [None] * (budget + 1)
    dp[0] = (0.0, [])
    for i in range(n):
        l = lengths[i]
        s = scores[i]
        for c in range(budget, l - 1, -1):
            if dp[c - l] is not None:
                new_score = dp[c - l][0] + s
                if dp[c] is None or new_score > dp[c][0]:
                    dp[c] = (new_score, dp[c - l][1] + [i])
    best = None
    for c in range(budget + 1):
        if dp[c] is not None:
            if best is None or dp[c][0] > best[0]:
                best = (dp[c][0], dp[c][1], c)
    return {
        "selected_indices": best[1],
        "tokens_used": best[2],
        "total_score": best[0]
    }"}
